<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabaseClient'
const houses = ref<any[]>([]); const drawer = ref(false); const editing = ref<any>(null); const search = ref(''); const saving = ref(false); const errorMessage = ref(''); const itemsPerPage = ref(10); const page = ref(1)
const form = ref({ house_name: '', address: '', principal_username: '', principal_email: '', status: 'Active' })
const load = async () => { const { data, error } = await supabase.from('houses').select('*').order('created_at', { ascending: false }); if (error) errorMessage.value = error.message; else houses.value = data || [] }
const openAdd = () => { editing.value = null; form.value = { house_name: '', address: '', principal_username: '', principal_email: '', status: 'Active' }; errorMessage.value = ''; drawer.value = true }
const openEdit = (house: any) => { editing.value = house; form.value = { house_name: house.house_name, address: house.address, principal_username: house.principal_username, principal_email: house.principal_email, status: house.status }; errorMessage.value = ''; drawer.value = true }
const save = async () => { saving.value = true; errorMessage.value = ''; const principalResult = await supabase.from('app_users').select('id, username, email, role, is_active').ilike('email', form.value.principal_email.trim()).maybeSingle(); if (principalResult.error) { errorMessage.value = `Unable to verify Principal account: ${principalResult.error.message}`; saving.value = false; return }; const principal = principalResult.data; if (!principal) { errorMessage.value = 'Principal email does not exist in app_users.'; saving.value = false; return }; if (String(principal.role).trim().toLowerCase() !== 'principal') { errorMessage.value = 'The selected account must have the Principal role.'; saving.value = false; return }; if (principal.is_active === false) { errorMessage.value = 'The Principal account is inactive.'; saving.value = false; return }; const result = editing.value ? await supabase.from('houses').update({ ...form.value, updated_at: new Date().toISOString() }).eq('id', editing.value.id) : await supabase.from('houses').insert(form.value); saving.value = false; if (result.error) errorMessage.value = result.error.code === '23505' ? 'This Principal email or username is already assigned.' : result.error.message; else { drawer.value = false; await load() } }
const toggleStatus = async (house: any) => { await supabase.from('houses').update({ status: house.status === 'Active' ? 'Inactive' : 'Active', updated_at: new Date().toISOString() }).eq('id', house.id); await load() }
const filtered = computed(() => houses.value.filter(h => !search.value || `${h.house_name} ${h.address} ${h.principal_username}`.toLowerCase().includes(search.value.toLowerCase())))
onMounted(load)
</script>
<template><section><div class="d-flex align-center gap-4 mb-6"><h4 class="text-h4 mb-0">House Management</h4></div><VCard><VCardText class="d-flex justify-space-between align-center flex-wrap gap-4"><AppSelect v-model="itemsPerPage" :items="[5, 10, 15, 20]" style="inline-size:90px" @update:model-value="page = 1"/><div class="d-flex align-center gap-4"><AppTextField v-model="search" placeholder="Search" prepend-inner-icon="tabler-search" style="inline-size:220px; max-inline-size:220px"/><VBtn color="primary" prepend-icon="tabler-plus" @click="openAdd">Add House</VBtn></div></VCardText><VDivider/><VCardText><VAlert v-if="errorMessage" type="error" variant="tonal" class="mb-4">{{ errorMessage }}</VAlert><VTable class="text-no-wrap"><thead><tr><th>House Name</th><th>Address</th><th>Principal Name</th><th>Created At</th><th>Updated At</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="house in filtered.slice((page - 1) * Number(itemsPerPage), page * Number(itemsPerPage))" :key="house.id"><td>{{ house.house_name }}</td><td>{{ house.address }}</td><td>{{ house.principal_username }}</td><td>{{ new Date(house.created_at).toLocaleString() }}</td><td>{{ new Date(house.updated_at).toLocaleString() }}</td><td><VChip size="small" :color="house.status === 'Active' ? 'success' : 'secondary'">{{ house.status === 'Active' ? 'Active' : 'Inactive' }}</VChip></td><td><VMenu><template #activator="{ props }"><VBtn v-bind="props" icon="tabler-dots-vertical" variant="text" /></template><VList density="compact"><VListItem prepend-icon="tabler-edit" title="Edit" @click="openEdit(house)"/><VListItem prepend-icon="tabler-player-pause" :title="house.status === 'Active' ? 'Deactivate' : 'Activate'" @click="toggleStatus(house)"/></VList></VMenu></td></tr><tr v-if="!filtered.length"><td colspan="7" class="text-center py-6">No houses found.</td></tr></tbody></VTable></VCardText><VDivider/><VCardText class="d-flex justify-space-between align-center text-medium-emphasis"><span>Showing {{ filtered.length ? ((page - 1) * Number(itemsPerPage) + 1) : 0 }} to {{ Math.min(page * Number(itemsPerPage), filtered.length) }} of {{ filtered.length }} entries</span><TablePagination v-model:page="page" :items-per-page="itemsPerPage" :total-items="filtered.length"/></VCardText></VCard><VNavigationDrawer v-model="drawer" location="end" temporary :width="460"><AppDrawerHeaderSection :title="editing ? 'Edit House' : 'Add New House'" @cancel="drawer = false"/><VDivider/><VCard flat><VCardText><VForm @submit.prevent="save"><AppTextField v-model="form.house_name" label="House Name" class="mb-4"/><AppTextField v-model="form.address" label="House Address" class="mb-4"/><VDivider class="my-4"/><div class="text-subtitle-2 mb-3">Add Principal User</div><AppTextField v-model="form.principal_username" label="Username" class="mb-4"/><AppTextField v-model="form.principal_email" type="email" label="Email" class="mb-4"/><div class="d-flex justify-end gap-3"><VBtn variant="text" @click="drawer = false">Cancel</VBtn><VBtn type="submit" color="primary" :loading="saving">{{ editing ? 'Save Changes' : 'Add House' }}</VBtn></div></VForm></VCardText></VCard></VNavigationDrawer></section></template>
